from pathlib import Path
p=Path('src/features/surveillance/PatientClinicalCanonicalPage.jsx')
s=p.read_text(encoding='utf-8')

def rep(a,b):
 global s
 if a not in s: raise SystemExit('missing: '+a[:100])
 s=s.replace(a,b,1)

# Report action: clinical printable report (browser PDF workflow) instead of raw JSON.
rep("{id:'download',label:language==='el'?'Λήψη δεδομένων':'Download data',icon:Download,onClick:()=>downloadRecordJson(detailRecord,{filename:`surveillance-${detailRecord.id}`})}","{id:'download',label:language==='el'?'Αναφορά επιτήρησης (PDF)':'Surveillance report (PDF)',icon:Download,onClick:()=>printSurveillanceReport(detailRecord,{language,fmtDate,fmtDateTime,t})}")
# Pass language into journey.
rep('t={t} fmtDate={fmtDate} fmtDateTime={fmtDateTime} permissions={permissions}/>', 't={t} language={language} fmtDate={fmtDate} fmtDateTime={fmtDateTime} permissions={permissions}/>')
rep('function CanonicalJourney({record,repository,onReload,t,fmtDate,fmtDateTime,permissions})','function CanonicalJourney({record,repository,onReload,t,language,fmtDate,fmtDateTime,permissions})')
# Friendly action labels.
rep("{record.assessment?t('edit'):`+ ${t('clinicalAssessment')}`}","{record.assessment?(language==='el'?'Επεξεργασία αξιολόγησης':'Edit assessment'):(language==='el'?'Νέα κλινική αξιολόγηση':'New clinical assessment')}")
rep(">+ {t('laboratoryRecords.newSample')}</Button>",">{language==='el'?'Νέο δείγμα':'New sample'}</Button>")
rep(">+ HAI</Button>",">{language==='el'?'Νέα αξιολόγηση HAI':'New HAI assessment'}</Button>")
rep(">+ AMR</Button>",">{language==='el'?'Νέα ταξινόμηση AMR':'New AMR classification'}</Button>")
rep(">+ {t('therapy')}</Button>",">{language==='el'?'Νέα αντιμικροβιακή αγωγή':'New antimicrobial therapy'}</Button>")
rep(">+ {t('isolation')}</Button>",">{language==='el'?'Έναρξη απομόνωσης':'Start isolation'}</Button>")
rep(">+ {t('reassessment')}</Button>",">{language==='el'?'Νέα επανεκτίμηση':'New reassessment'}</Button>")
# Translate coded assessment tags.
rep("<TagList title={t('signsSymptoms')} items={record.assessment.signsSymptoms||record.assessment.symptoms}/><TagList title={t('riskFactors')} items={record.assessment.riskFactors}/>","<TagList title={t('signsSymptoms')} items={record.assessment.signsSymptoms||record.assessment.symptoms} t={t} language={language}/><TagList title={t('riskFactors')} items={record.assessment.riskFactors} t={t} language={language}/>")
rep("function TagList({title,items=[]}){if(!items?.length)return null;return <><h4>{title}</h4><div className=\"tag-row\">{items.map(x=><span className=\"clinical-tag\" key={x}>{x}</span>)}</div></>}","function TagList({title,items=[],t,language}){if(!items?.length)return null;return <><h4>{title}</h4><div className=\"tag-row\">{items.map(x=><span className=\"clinical-tag\" key={x}>{clinicalValueLabel(x,language,t)}</span>)}</div></>}")
# Make clinical record rows clickable and add selected-entry detail dialog.
rep("const [stage,setStage]=useState('assessment'),[dialog,setDialog]=useState(null),[reason,setReason]=useState('');", "const [stage,setStage]=useState('assessment'),[dialog,setDialog]=useState(null),[reason,setReason]=useState(''),[entryDetail,setEntryDetail]=useState(null);")
rep("<tbody>{record.samples.map(x=><tr key={x.id}><td>","<tbody>{record.samples.map(x=><tr key={x.id} className=\"clickable-row\" tabIndex={0} onClick={()=>setEntryDetail({kind:'sample',row:x})} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setEntryDetail({kind:'sample',row:x})}}><td>")
rep("<tbody>{record.therapy.map(x=><tr key={x.id}><td><strong>","<tbody>{record.therapy.map(x=><tr key={x.id} className=\"clickable-row\" tabIndex={0} onClick={()=>setEntryDetail({kind:'therapy',row:x})} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setEntryDetail({kind:'therapy',row:x})}}><td><strong>")
rep("{record.reassessments.map(x=><article key={x.id}><div>","{record.reassessments.map(x=><article key={x.id} className=\"clickable-entry\" tabIndex={0} onClick={()=>setEntryDetail({kind:'reassessment',row:x})} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setEntryDetail({kind:'reassessment',row:x})}}><div>")
# Add detail modal near end of active journey.
needle="{dialog==='outcome'&&<OutcomeDialog t={t} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.complete(record,draft),t('clinicalRecords.outcomeSaved'))}/>}</div>}"
insert="{dialog==='outcome'&&<OutcomeDialog t={t} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.complete(record,draft),t('clinicalRecords.outcomeSaved'))}/>} {entryDetail&&<ClinicalEntryDetail entry={entryDetail} record={record} t={t} language={language} fmtDate={fmtDate} canManage={active} onClose={()=>setEntryDetail(null)} onEdit={()=>{const kind=entryDetail.kind;setEntryDetail(null);if(kind==='therapy')return;setDialog(kind==='sample'?'sample':kind)}} onFinishTherapy={entryDetail.kind==='therapy'&&entryDetail.row?.status==='active'&&permissions.canTherapy?()=>{const row=entryDetail.row;setEntryDetail(null);run(()=>repository.finishTherapy(record,row.id,{endedAt:new Date().toISOString().slice(0,10)}),t('actionCompleted'))}:null}/>}</div>}"
rep(needle,insert)
# Helpers before StagePanel.
marker='function StagePanel({icon:Icon,title,action,children})'
helper=r'''function ClinicalEntryDetail({entry,t,language,fmtDate,canManage,onClose,onEdit,onFinishTherapy}){const row=entry.row||{};const titleMap={sample:language==='el'?'Λεπτομέρειες δείγματος':'Sample details',therapy:language==='el'?'Λεπτομέρειες αντιμικροβιακής αγωγής':'Antimicrobial therapy details',reassessment:language==='el'?'Λεπτομέρειες επανεκτίμησης':'Reassessment details'};const fields=entry.kind==='sample'?[[language==='el'?'Κωδικός δείγματος':'Sample code',row.id],[t('sampleType'),clinicalValueLabel(row.type||row.sampleType,language,t)],[t('status'),clinicalValueLabel(row.result||row.status||'pending',language,t)],[t('organism'),row.organism||'—'],['AMR',row.resistance||'—']]:entry.kind==='therapy'?[[language==='el'?'Αντιμικροβιακό':'Antimicrobial',row.antimicrobial],[language==='el'?'Δόση':'Dose',row.dose],[language==='el'?'Οδός χορήγησης':'Route',clinicalValueLabel(row.route,language,t)],[language==='el'?'Έναρξη':'Started',fmtDate(row.startedAt)],[t('status'),clinicalValueLabel(row.status||'active',language,t)]]:[[language==='el'?'Ημερομηνία':'Date',fmtDate(row.date)],[t('status'),clinicalValueLabel(row.status,language,t)],[language==='el'?'Σημειώσεις':'Notes',row.notes||'—'],[language==='el'?'Επόμενη επανεκτίμηση':'Next review',fmtDate(row.nextReviewDue)]];return <ObserverDialog title={titleMap[entry.kind]||t('details')} onClose={onClose}><div className="detail-grid clinical-entry-detail-grid">{fields.map(([label,value])=><Detail key={label} label={label} value={value}/>)}</div><div className="dialog-actions">{entry.kind==='sample'&&canManage&&<span className="entry-detail-note">{language==='el'?'Η καταχώριση αποτελέσματος/διόρθωση γίνεται από το Εργαστήριο ώστε να διατηρείται πλήρες audit trail.':'Results and corrections are managed by Laboratory to preserve the audit trail.'}</span>}{entry.kind==='reassessment'&&canManage&&<span className="entry-detail-note">{language==='el'?'Οι επανεκτιμήσεις παραμένουν ιστορικές. Για αλλαγή καταχωρείται νέα επανεκτίμηση.':'Reassessments remain historical; record a new reassessment for a change.'}</span>}{entry.kind==='therapy'&&onFinishTherapy&&<Button variant="secondary" onClick={onFinishTherapy}>{language==='el'?'Ολοκλήρωση αγωγής':'End therapy'}</Button>}{entry.kind==='reassessment'&&canManage&&<Button onClick={onEdit}>{language==='el'?'Νέα επανεκτίμηση':'New reassessment'}</Button>}</div></ObserverDialog>}
function escapeReport(value){return String(value??'—').replace(/[&<>\"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[ch]))}
function printSurveillanceReport(record,{language,fmtDate,fmtDateTime,t}){const el=language==='el';const label=value=>escapeReport(clinicalValueLabel(value,language,t));const rows=(items,render)=>items?.length?items.map(render).join(''):`<tr><td colspan="5">${el?'Δεν υπάρχουν καταχωρίσεις':'No records'}</td></tr>`;const symptoms=(record.assessment?.signsSymptoms||record.assessment?.symptoms||[]).map(label).join(', ')||'—';const risks=(record.assessment?.riskFactors||[]).map(label).join(', ')||'—';const html=`<!doctype html><html><head><meta charset="utf-8"><title>${el?'Αναφορά επιτήρησης':'Surveillance report'} ${escapeReport(record.id)}</title><style>body{font-family:Arial,sans-serif;color:#17324d;margin:28px;font-size:12px}h1{font-size:22px;margin:0 0 4px}h2{font-size:15px;margin:24px 0 8px;border-bottom:1px solid #cbd8e5;padding-bottom:5px}.meta{color:#60758a}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px 20px}.item{border:1px solid #d8e2ec;border-radius:7px;padding:8px}.item span{display:block;color:#718399;font-size:10px}.item strong{display:block;margin-top:3px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #dde5ed;padding:7px 5px;vertical-align:top}th{font-size:10px;color:#61758a}.footer{margin-top:28px;padding-top:8px;border-top:1px solid #ccd8e4;color:#708297;font-size:10px}@media print{body{margin:12mm}.no-print{display:none}}</style></head><body><h1>${el?'Αναλυτική αναφορά επιτήρησης':'Detailed surveillance report'}</h1><div class="meta">${escapeReport(record.id)} · ${fmtDate(record.startedAt)} · ${label(record.status)}</div><h2>${el?'Στοιχεία επεισοδίου':'Episode details'}</h2><div class="grid"><div class="item"><span>${el?'Ημερομηνία έναρξης':'Start date'}</span><strong>${fmtDate(record.startedAt)}</strong></div><div class="item"><span>${el?'Τμήμα':'Department'}</span><strong>${escapeReport(record.department||record.departmentEn)}</strong></div><div class="item"><span>${el?'Λόγος επιτήρησης':'Surveillance reason'}</span><strong>${escapeReport(record.reason)}</strong></div><div class="item"><span>${el?'Πιθανή εστία':'Suspected source'}</span><strong>${label(record.suspectedSource)}</strong></div></div><h2>${el?'Κλινική αξιολόγηση':'Clinical assessment'}</h2><div class="grid"><div class="item"><span>${el?'Ταξινόμηση':'Classification'}</span><strong>${label(record.assessment?.classification||'undetermined')}</strong></div><div class="item"><span>${el?'Ημερομηνία':'Date'}</span><strong>${fmtDate(record.assessment?.date)}</strong></div><div class="item"><span>${el?'Σημεία / συμπτώματα':'Signs / symptoms'}</span><strong>${symptoms}</strong></div><div class="item"><span>${el?'Παράγοντες κινδύνου':'Risk factors'}</span><strong>${risks}</strong></div></div><h2>${el?'Δείγματα και μικροβιολογία':'Samples and microbiology'}</h2><table><thead><tr><th>${el?'Δείγμα':'Sample'}</th><th>${el?'Τύπος':'Type'}</th><th>${el?'Κατάσταση':'Status'}</th><th>${el?'Μικροοργανισμός':'Organism'}</th><th>AMR</th></tr></thead><tbody>${rows(record.samples,x=>`<tr><td>${escapeReport(x.id)}</td><td>${label(x.type)}</td><td>${label(x.result||x.status||'pending')}</td><td>${escapeReport(x.organism)}</td><td>${escapeReport(x.resistance)}</td></tr>`)}</tbody></table><h2>${el?'HAI / AMR':'HAI / AMR'}</h2><div class="grid"><div class="item"><span>HAI</span><strong>${escapeReport(record.haiClassification?.type)} · ${label(record.haiClassification?.status)}</strong></div><div class="item"><span>AMR</span><strong>${escapeReport(record.resistance)}</strong></div></div><h2>${el?'Απομόνωση':'Isolation'}</h2><div class="grid"><div class="item"><span>${el?'Κατάσταση':'Status'}</span><strong>${record.isolation?label(record.isolation.status):(record.isolationDecision?.required===false?(el?'Δεν απαιτείται':'Not required'):'—')}</strong></div><div class="item"><span>${el?'Έναρξη':'Started'}</span><strong>${fmtDate(record.isolation?.startedAt)}</strong></div></div><h2>${el?'Αντιμικροβιακή αγωγή':'Antimicrobial therapy'}</h2><table><thead><tr><th>${el?'Αντιμικροβιακό':'Antimicrobial'}</th><th>${el?'Δόση':'Dose'}</th><th>${el?'Οδός':'Route'}</th><th>${el?'Έναρξη':'Started'}</th><th>${el?'Κατάσταση':'Status'}</th></tr></thead><tbody>${rows(record.therapy,x=>`<tr><td>${escapeReport(x.antimicrobial)}</td><td>${escapeReport(x.dose)}</td><td>${label(x.route)}</td><td>${fmtDate(x.startedAt)}</td><td>${label(x.status||'active')}</td></tr>`)}</tbody></table><h2>${el?'Επανεκτιμήσεις':'Reassessments'}</h2><table><thead><tr><th>${el?'Ημερομηνία':'Date'}</th><th>${el?'Κατάσταση':'Status'}</th><th colspan="3">${el?'Σημειώσεις':'Notes'}</th></tr></thead><tbody>${rows(record.reassessments,x=>`<tr><td>${fmtDate(x.date)}</td><td>${label(x.status)}</td><td colspan="3">${escapeReport(x.notes)}</td></tr>`)}</tbody></table><h2>${el?'Έκβαση':'Outcome'}</h2><div class="grid"><div class="item"><span>${el?'Κατάσταση':'Status'}</span><strong>${label(record.outcome?.status)}</strong></div><div class="item"><span>${el?'Ημερομηνία':'Date'}</span><strong>${fmtDate(record.outcome?.date)}</strong></div></div><h2>${el?'Ιστορικό ενεργειών':'Activity history'}</h2><table><thead><tr><th>${el?'Ημερομηνία / ώρα':'Date / time'}</th><th>${el?'Ενέργεια':'Action'}</th><th colspan="3">${el?'Λεπτομέρεια':'Detail'}</th></tr></thead><tbody>${rows(record.timeline,x=>`<tr><td>${fmtDateTime(x.at)}</td><td>${label(x.type)}</td><td colspan="3">${escapeReport(x.detail)}</td></tr>`)}</tbody></table><div class="footer">Limoxis Observer · ${el?'Αναφορά κλινικής επιτήρησης':'Clinical surveillance report'} · ${new Date().toLocaleString(language==='el'?'el-GR':'en-GB')}</div><script>window.onload=()=>{window.print()}<\/script></body></html>`;const w=window.open('','_blank','noopener,noreferrer');if(!w)return;w.document.open();w.document.write(html);w.document.close()}
'''
rep(marker,helper+marker)
# Extend terminology fallback for visible clinical codes.
needle2="const labels={"
idx=s.find(needle2,s.find('function clinicalValueLabel'))
if idx<0: raise SystemExit('clinicalValueLabel labels not found')
start=idx+len(needle2)
s=s[:start]+"FEVER:language==='el'?'Πυρετός':'Fever',CHILLS:language==='el'?'Ρίγος':'Chills',ICU_STAY:language==='el'?'Νοσηλεία σε ΜΕΘ':'ICU stay',undetermined:language==='el'?'Δεν έχει ακόμη ταξινομηθεί':'Not yet classified',created:language==='el'?'Δημιουργία επιτήρησης':'Surveillance created',no:language==='el'?'Όχι':'No',"+s[start:]
p.write_text(s,encoding='utf-8')

css=Path('src/styles/patient-record.css')
c=css.read_text(encoding='utf-8')
addon='''\n/* Surveillance clinical record interaction */\n.clickable-entry{cursor:pointer;border-radius:8px}.clickable-entry:hover,.clickable-entry:focus-visible{background:var(--surface-subtle,#f7fafc);outline:none}.clinical-entry-detail-grid{margin:8px 0 4px}.entry-detail-note{max-width:520px;color:var(--text-muted,#66788a);font-size:.82rem;line-height:1.45;margin-right:auto}.record-table .clickable-row{cursor:pointer}.record-table .clickable-row:hover{background:var(--surface-subtle,#f7fafc)}\n'''
if 'Surveillance clinical record interaction' not in c: css.write_text(c+addon,encoding='utf-8')
